function tamanhoIngenuo<T>(valor: T): number {
  // @ts-expect-error T sem restrição pode ser qualquer coisa, incluindo number, e nada garante length
  return valor.length;
}

function tamanho<T extends { length: number }>(valor: T): number {
  return valor.length;
}

console.log(tamanho("constraints"));            // 11
console.log(tamanho([1, 2, 3]));                // 3
console.log(tamanho({ length: 7, unidade: "cm" })); // 7

// @ts-expect-error number não tem length, por isso não satisfaz a constraint
tamanho(42);

interface ComTamanho {
  length: number;
}

function maisLongo<T extends ComTamanho>(a: T, b: T): T {
  return a.length >= b.length ? a : b;
}

const texto = maisLongo("europeu", "pt");
console.log(texto.toUpperCase()); // EUROPEU

const lista = maisLongo([1, 2], [1, 2, 3]);
console.log(lista.length); // 3

function descrever<T extends ComTamanho>(valor: T): string {
  // @ts-expect-error a constraint só promete length; não promete métodos de string
  valor.toUpperCase();
  return `tem ${valor.length}`;
}

interface Identificavel {
  id: string;
}

interface Utilizador extends Identificavel {
  nome: string;
  idade: number;
}

function indexarPorId<T extends Identificavel>(itens: readonly T[]): Map<string, T> {
  const mapa = new Map<string, T>();
  for (const item of itens) {
    mapa.set(item.id, item);
  }
  return mapa;
}

const utilizadores: Utilizador[] = [
  { id: "u1", nome: "Ana", idade: 34 },
  { id: "u2", nome: "Rui", idade: 41 },
];

console.log(indexarPorId(utilizadores).get("u2")?.nome); // Rui

type Direcao = "asc" | "desc";

function ordenar<D extends Direcao>(valores: readonly number[], direcao: D): number[] {
  const copia = [...valores];
  copia.sort((a, b) => (direcao === "asc" ? a - b : b - a));
  return copia;
}

console.log(ordenar([3, 1, 2], "desc")); // [ 3, 2, 1 ]

// @ts-expect-error "crescente" não pertence à união imposta pela constraint
ordenar([3, 1, 2], "crescente");

interface Animal {
  nome: string;
}

interface Cao extends Animal {
  raca: string;
  ladrar(): string;
}

function registarGenerico<T extends Animal>(animal: T): T {
  console.log(`registado: ${animal.nome}`);
  return animal;
}

function registarSimples(animal: Animal): Animal {
  console.log(`registado: ${animal.nome}`);
  return animal;
}

const bobi: Cao = { nome: "Bobi", raca: "serra da estrela", ladrar: () => "au" };

const comGenerico = registarGenerico(bobi); // o tipo devolvido é Cao
console.log(comGenerico.ladrar()); // au

const semGenerico = registarSimples(bobi); // o tipo devolvido é Animal
// @ts-expect-error o parâmetro não genérico colapsou o valor em Animal e perdeu ladrar
semGenerico.ladrar();

function obterPropriedade<T extends object, K extends keyof T>(objeto: T, chave: K): T[K] {
  return objeto[chave];
}

const livro = { titulo: "Contos", paginas: 210, esgotado: false };

const titulo = obterPropriedade(livro, "titulo");   // string
const paginas = obterPropriedade(livro, "paginas"); // number
console.log(titulo.toUpperCase(), paginas + 1); // CONTOS 211

// @ts-expect-error "autor" não é chave de livro, logo não satisfaz K extends keyof T
obterPropriedade(livro, "autor");

interface Caixa<T = string> {
  conteudo: T;
  etiqueta: string;
}

const caixaTexto: Caixa = { conteudo: "manual", etiqueta: "docs" };
const caixaMedidas: Caixa<number[]> = { conteudo: [1, 2, 3], etiqueta: "medidas" };

console.log(caixaTexto.conteudo.toUpperCase()); // MANUAL
console.log(caixaMedidas.conteudo.length);      // 3

function criarLista<T = number>(...itens: T[]): T[] {
  return itens;
}

const vazia = criarLista();          // number[], vindo do tipo por omissão
const letras = criarLista("a", "b"); // string[], a inferência ganha à omissão
console.log(vazia.length, letras.join("-")); // 0 a-b

// @ts-expect-error um parâmetro de tipo obrigatório não pode vir depois de um com omissão
interface ParOrdenado<A = string, B> {
  primeiro: A;
  segundo: B;
}

interface Evento {
  tipo: string;
}

interface Clique extends Evento {
  tipo: "clique";
  x: number;
  y: number;
}

class Registo<T extends Evento = Evento> {
  private readonly itens: T[] = [];

  adicionar(evento: T): void {
    this.itens.push(evento);
  }

  tipos(): string[] {
    return this.itens.map((item) => item.tipo);
  }
}

const generico = new Registo();
generico.adicionar({ tipo: "arranque" });
console.log(generico.tipos()); // [ 'arranque' ]

const cliques = new Registo<Clique>();
cliques.adicionar({ tipo: "clique", x: 10, y: 4 });
console.log(cliques.tipos()); // [ 'clique' ]

// @ts-expect-error string não satisfaz a constraint, mesmo havendo tipo por omissão
const invalido = new Registo<string>();

function exigenteDemais<T extends { id: string; nome: string; email: string }>(
  itens: readonly T[],
): T | undefined {
  return itens[0];
}

// @ts-expect-error a constraint exige campos que a função nem sequer chega a usar
exigenteDemais([{ id: "a" }]);

function naMedida<T extends { id: string }>(itens: readonly T[]): T | undefined {
  return itens[0];
}

console.log(naMedida([{ id: "a" }, { id: "b" }])); // { id: 'a' }

