function iniciais<T extends { nome: string }>(itens: readonly T[]): string[] {
  return itens.map((item) => item.nome.charAt(0).toUpperCase());
}

const equipa = [
  { nome: "ana", cargo: "design" },
  { nome: "rui", cargo: "backend" },
];

console.log(iniciais(equipa)); // [ 'A', 'R' ]

const cidades = [{ nome: "Braga", habitantes: 193333 }];
console.log(iniciais(cidades)); // [ 'B' ]

try {
  // @ts-expect-error os objetos não têm a propriedade nome exigida pela constraint
  console.log(iniciais([{ titulo: "sem nome" }]));
} catch {
  console.log("sem nome para ler"); // sem nome para ler
}

class Pilha<T = string> {
  private readonly itens: T[] = [];

  empilhar(item: T): void {
    this.itens.push(item);
  }

  desempilhar(): T | undefined {
    return this.itens.pop();
  }

  get tamanho(): number {
    return this.itens.length;
  }
}

const textos = new Pilha();
textos.empilhar("primeiro");
textos.empilhar("segundo");
console.log(textos.desempilhar()?.toUpperCase()); // SEGUNDO
console.log(textos.tamanho); // 1

const numeros = new Pilha<number>();
numeros.empilhar(7);
console.log(numeros.desempilhar()); // 7

// @ts-expect-error a pilha por omissão é de string, e 42 não é string
textos.empilhar(42);

function extrairColuna<T extends object, K extends keyof T>(
  itens: readonly T[],
  chave: K,
): T[K][] {
  return itens.map((item) => item[chave]);
}

const produtos = [
  { referencia: "A1", preco: 12.5, stock: 4 },
  { referencia: "B2", preco: 30, stock: 0 },
];

const precos = extrairColuna(produtos, "preco");
console.log(precos.reduce((total, preco) => total + preco, 0)); // 42.5

const referencias = extrairColuna(produtos, "referencia");
console.log(referencias.join(", ")); // A1, B2

// @ts-expect-error "iva" não é chave dos produtos, logo não satisfaz K extends keyof T
extrairColuna(produtos, "iva");

interface Identificavel {
  id: string;
}

interface Tarefa extends Identificavel {
  titulo: string;
  concluida: boolean;
}

class Repositorio<T extends Identificavel = Identificavel> {
  private readonly registos = new Map<string, T>();

  guardar(item: T): T {
    this.registos.set(item.id, item);
    return item;
  }

  obter(id: string): T | undefined {
    return this.registos.get(id);
  }

  quantidade(): number {
    return this.registos.size;
  }
}

const tarefas = new Repositorio<Tarefa>();
const guardada = tarefas.guardar({ id: "t1", titulo: "Rever o PR", concluida: false });
console.log(guardada.titulo); // Rever o PR
console.log(tarefas.obter("t1")?.concluida); // false

const generico = new Repositorio();
generico.guardar({ id: "x1" });
console.log(generico.quantidade()); // 1

// @ts-expect-error o tipo por omissão só promete id, e titulo não existe em Identificavel
generico.obter("x1")?.titulo;

// @ts-expect-error number não satisfaz a constraint T extends Identificavel
const invalido = new Repositorio<number>();
